async function main(req) {
  const secret = env('WEBHOOK_SECRET');
  if (!secret) return { error: 'WEBHOOK_SECRET not configured', status: 500 };

  const signature = (req.headers || {})['X-Signature'] || (req.headers || {})['x-signature'] || '';
  const body = req.body || '';

  // Verify HMAC signature
  const expectedSig = await sha256(secret + ':' + body);

  if (!signature) {
    log('webhook received without signature');
    return { error: 'missing signature header', status: 401 };
  }

  if (signature !== expectedSig) {
    log('webhook signature mismatch');
    return { error: 'invalid signature', status: 403 };
  }

  // Process the verified webhook payload
  const payload = jsonParse(body, {});
  const event = payload.event || 'unknown';

  log('verified webhook event:', event);

  switch (event) {
    case 'user.created':
      return { processed: true, event, action: 'send_welcome_email', user: payload.data };
    case 'payment.completed':
      return { processed: true, event, action: 'fulfill_order', order: payload.data };
    case 'subscription.cancelled':
      return { processed: true, event, action: 'schedule_offboarding', account: payload.data };
    default:
      return { processed: false, event, message: 'unhandled event type' };
  }
}
